import React from 'react'
import { connect } from 'react-redux'
import { Col, Upload, Button, message } from 'antd'
import UploaderStyled from './uploader.style'
import promoAction from '../../redux/promo/actions'

const { uploadCouponImage } = promoAction

const Dragger = Upload.Dragger

const dummyRequest = ({ file, onSuccess }) => {
  setTimeout(() => {
    onSuccess('ok')
  }, 0)
}

class Uploader extends React.Component {
    state = {
      loading: false
    }
    componentWillReceiveProps (nextProps) {
      const status = nextProps.uploadStatus
      if (status === 'success') {
        this.setState({ loading: false })
      }
    }
    async handleChange (info) {
      if (info.file.status === 'done' || info.file.status === 'error') {
        const isLt10KB = info.file.size / 1024 / 1024 < 0.01
        const isGt20MB = info.file.size / 1024 / 1024 > 20
        if (isLt10KB) {
          message.error('Image is to small, min 10kb')
          return
        }
        if (isGt20MB) {
          message.error('Image is to big, max 20mb')
          return
        }
        if ((info.file.type === 'image/jpeg' || info.file.type === 'image/jpg' || info.file.type === 'image/png' && !isLt10KB && !isGt20MB)) { // eslint-disable-line
          const file = info.file.originFileObj
          this.setState({
            filename: file.name,
            filesize: file.size,
            file
          })
        } else {
          message.error('File is not supported')
        }
      }
    }
    startUpload = () => {
      this.setState({ loading: true })
      let formData = new FormData()
      formData.append('file', this.state.file)
      formData.append('name', this.props.name)
      this.props.uploadCouponImage(formData)
    }
    render () {
      return (
        <Col span={8} style={{ display: 'flex', justifyContent: 'space-between' }}>
          <UploaderStyled>
            <Dragger
              name='file'
              showUploadList={false}
              multiple={false}
              customRequest={dummyRequest}
              onChange={file => this.handleChange(file)}
            >
              {this.state.filename !== undefined ? (
                <div style={{ display: 'flex', justifyContent: 'center' }}>
                  <p>{this.state.filename}</p>&nbsp;&nbsp;
                  <p>{this.state.filesize / 1000}kb</p>
                </div>
              ) : <p>Choose</p>}
            </Dragger>
          </UploaderStyled>
          <Button
            loading={this.state.loading}
            type='primary'
            disabled={this.state.filename === undefined}
            onClick={this.startUpload}
          >
                    Upload
          </Button>
        </Col>
      )
    }
}

export default connect(
  state => ({
    uploadStatus: state.PromoDetails.status
  }),
  { uploadCouponImage }
)(Uploader)
